FilterCalc.Calculation:
日計平均推移::年度 =
Case (
    GetAsNumber ( Right ( 計画進捗::年月 ; 2 ) ) ≤ 3 ;
    Left ( 計画進捗::年月 ; 4 ) - 1 ;
    Left ( 計画進捗::年月 ; 4 )
)
and 日計平均推移::日計平均推移分類 = "D+N業"
and Date ( 日計平均推移::月 + 1 ; 0 ; 日計平均推移::年 ) ≤ Date ( Right ( 計画進捗::年月_g ; 2 ) + 1 ; 0 ; Left ( 計画進捗::年月_g ; 4 ) )

